ctx.fillStyle='white';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText('▼',xPos,12);
if(lam>=400&&lam<=780){var h=270-(lam-400)/380*270;ctx.fillStyle='hsl('+h+',100%,55%)';ctx.fillRect(xPos-8,54,16,10);}
var vl=lam<0.01?lam.toExponential(2):lam>1e6?lam.toExponential(2):lam.toFixed(0);
container.querySelector('#em-vl').textContent=vl;
container.querySelector('#em-ve').textContent=(1240/Math.max(1e-6,lam)).toExponential(2);
var r=REG.find(function(x){return lam>=x.l&&lam<x.r;})||REG[REG.length-1];
var re=container.querySelector('#em-reg');
re.textContent=r.n;re.style.color=r.c;re.style.borderLeft='3px solid '+r.c;
container.querySelector('#em-app').textContent=r.a;}
container.querySelector('#em-lam').addEventListener('input',draw);draw();

var cv=container.querySelector('#sn-cv'),ctx=cv.getContext('2d');
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=150;
var n1=+container.querySelector('#sn-n1').value,n2=+container.querySelector('#sn-n2').value,t1=+container.querySelector('#sn-t1').value*Math.PI/180;
