ctx.fillStyle='#4b5563';ctx.font='10px monospace';ctx.textAlign='left';ctx.fillText('n₁='+n1.toFixed(2),4,14);ctx.fillText('n₂='+n2.toFixed(2),4,90);
ctx.strokeStyle='rgba(255,255,255,0.2)';ctx.lineWidth=1;ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(0,cy);ctx.lineTo(W,cy);ctx.stroke();ctx.beginPath();ctx.moveTo(cx,10);ctx.lineTo(cx,140);ctx.stroke();ctx.setLineDash([]);
ctx.strokeStyle='#fbbf24';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx-L*Math.sin(t1),cy-L*Math.cos(t1));ctx.lineTo(cx,cy);ctx.stroke();
ctx.strokeStyle='rgba(251,191,36,0.35)';ctx.lineWidth=1.5;ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+L*Math.sin(t1),cy-L*Math.cos(t1));ctx.stroke();ctx.setLineDash([]);
