var cv=container.querySelector('#po-cv'),ctx=cv.getContext('2d');
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=110;
var th=+container.querySelector('#po-t').value*Math.PI/180;
var ratio=Math.pow(Math.cos(th),2);
container.querySelector('#po-vi').textContent=ratio.toFixed(3);container.querySelector('#po-ip').textContent=ratio.toFixed(3);
ctx.clearRect(0,0,W,110);var cx=W/2,cy=55,R=46;
ctx.strokeStyle='rgba(255,255,255,0.08)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,R,0,2*Math.PI);ctx.stroke();
ctx.strokeStyle='rgba(255,255,255,0.05)';ctx.beginPath();ctx.moveTo(cx-R,cy);ctx.lineTo(cx+R,cy);ctx.stroke();ctx.beginPath();ctx.moveTo(cx,cy-R);ctx.lineTo(cx,cy+R);ctx.stroke();
ctx.fillStyle='rgba(58,176,158,0.15)';ctx.beginPath();
for(var a=0;a<=2*Math.PI;a+=0.03){var r=R*Math.pow(Math.cos(a),2);var x=cx+r*Math.cos(a),y=cy+r*Math.sin(a);a===0?ctx.moveTo(x,y):ctx.lineTo(x,y);}
ctx.closePath();ctx.fill();ctx.strokeStyle='#3ab09e';ctx.lineWidth=1.5;ctx.stroke();
var curR=R*ratio;ctx.strokeStyle='#fbbf24';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+curR*Math.cos(th),cy+curR*Math.sin(th));ctx.stroke();
ctx.fillStyle='#fbbf24';ctx.beginPath();ctx.arc(cx+curR*Math.cos(th),cy+curR*Math.sin(th),3,0,2*Math.PI);ctx.fill();
ctx.fillStyle='#9ca3af';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('0°',cx+R+8,cy+3);ctx.fillText('90°',cx,cy-R-4);ctx.fillText('I=I₀',cx-R-15,cy+3);}
