var cv=container.querySelector('#di-cv'),ctx=cv.getContext('2d');
function draw(){var W=cv.offsetWidth||300;cv.width=W;cv.height=100;
var a=+container.querySelector('#di-a').value*1e-6,D=+container.querySelector('#di-D').value*1e-2,lam=+container.querySelector('#di-l').value*1e-9;
var i_um=(lam*D/a)*1e6;container.querySelector('#di-vi').textContent=i_um.toFixed(1);
var h=+container.querySelector('#di-l').value,hue=270-(h-380)/400*270;
container.querySelector('#di-color').innerHTML='<span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:hsl('+hue+',100%,55%);vertical-align:middle;margin-right:4px"></span>';
ctx.clearRect(0,0,W,100);var nFr=15,ip=W/nFr;
for(var k=-nFr;k<=nFr;k++){var xc=W/2+k*ip;if(xc<-ip||xc>W+ip)continue;
var bri=Math.pow(Math.cos(k*Math.PI/2),2);
var grd=ctx.createRadialGradient(xc,50,0,xc,50,ip*0.8);
grd.addColorStop(0,'hsla('+hue+',100%,65%,'+(bri*0.9)+')');grd.addColorStop(1,'hsla('+hue+',100%,65%,0)');
ctx.fillStyle=grd;ctx.fillRect(Math.max(0,xc-ip),0,ip*2,100);}
ctx.strokeStyle='rgba(255,255,255,0.4)';ctx.lineWidth=0.5;ctx.setLineDash([2,3]);
ctx.beginPath();ctx.moveTo(W/2,0);ctx.lineTo(W/2,100);ctx.stroke();ctx.setLineDash([]);
ctx.fillStyle='rgba(255,255,255,0.7)';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('0',W/2,95);}
['di-a','di-D','di-l'].forEach(function(id){container.querySelector('#'+id).addEventListener('input',draw);});draw();

